local underwater_chunks = {
"--!strict\n--[[\n    UnderwaterController.client.lua\n    Immersive underwater audiovisual and post-processing engine for \"Don't Let the Fire Die\".\n    Developed for Fluenosity Studio.\n\n    Features:\n    - Real-time voxel-accurate camera water submersion detection with hysteresis.\n    - Smooth aquatic color grading (translucent cyan-blue tint, contrast, depth saturation).\n    - Optical water diffraction blur and natural depth fog attenuation.\n    - AAA low-pass audio muffling via MasterSoundGroup Equalizer.\n    - Floating micro-motes & rising bubble column visual juice.\n    - Zero swim physics (delegated cleanly to dedicated SwimmingController.client.lua).\n    - Zero jarring splash noise on water entry/exit.\n]]\n\nlocal RunService = game:GetService(\"RunService\")\nlocal Lighting = game:GetService(\"Lighting\")\nlocal SoundService = game:GetService(\"SoundService\")\nlocal Players = game:GetService(\"Players\")\n\nlocal UITheme = require(script.Parent:WaitForChild(\"UITheme\"))\n\nlocal localPlayer = Players.LocalPlayer\n\n-- -----------------------------------------------------------------------------\n-- 1. POST-PROCESSING INSTANCES SETUP\n-- -----------------------------------------------------------------------------\nlocal underwaterCC = Lighting:FindFirstChild(\"UnderwaterColorCorrection\") :: ColorCorrectionEffect?\nif not underwaterCC then\n    underwaterCC = Instance.new(\"ColorCorrectionEffect\")\n    underwaterCC.Name = \"UnderwaterColorCorrection\"\n    underwaterCC.TintColor = Color3.fromRGB(255, 255, 255)\n    underwaterCC.Saturation = 0\n    underwaterCC.Contrast = 0\n    underwaterCC.Brightness = 0\n    underwaterCC.Enabled = true\n    underwaterCC.Parent = Lighting\nend\n\nlocal underwaterBlur = Lighting:FindFirstChild(\"UnderwaterBlur\") :: BlurEffect?\nif not underwaterBlur then\n    underwaterBlur = Instance.new(\"BlurEffect\")\n    underwaterBlur.Name = \"UnderwaterBlur\"\n    underwaterBlur.Size = 0\n    underwaterBlur.Enabled = true\n    underwaterBlur.Parent = Lighting\nend\n\n-- -----------------------------------------------------------------------------\n-- 2. AUDIO MUFFLE (EQUALIZER) SETUP\n-- -----------------------------------------------------------------------------\nUITheme.InitAudioRouting()\nlocal masterSoundGroup = UITheme.GetMasterSoundGroup()\n\nlocal underwaterEQ = masterSoundGroup:FindFirstChild(\"UnderwaterEqualizer\") :: EqualizerSoundEffect?\nif not underwaterEQ then\n    underwaterEQ = Instance.new(\"EqualizerSoundEffect\")\n    underwaterEQ.Name = \"UnderwaterEqualizer\"\n    underwaterEQ.HighGain = 0\n    underwaterEQ.MidGain = 0\n    underwaterEQ.LowGain = 0\n    underwaterEQ.Priority = 10\n    underwaterEQ.Parent = masterSoundGroup\nend\n\n-- Clean up any obsolete/broken ambience loops from SoundService if previously created\nlocal oldAmbience = SoundService:FindFirstChild(\"UnderwaterAmbienceLoop\")\nif oldAmbience then\n    pcall(function() oldAmbience:Destroy() end)\nend\n\n-- -----------------------------------------------------------------------------\n",
"-- 3. UNDERWATER DRIFTING MOTES PARTICLE EMITTER\n-- -----------------------------------------------------------------------------\nlocal motePart = workspace.Terrain:FindFirstChild(\"UnderwaterMoteEmitter\") :: Part?\nif not motePart then\n    motePart = Instance.new(\"Part\")\n    motePart.Name = \"UnderwaterMoteEmitter\"\n    motePart.Size = Vector3.new(1, 1, 1)\n    motePart.Transparency = 1\n    motePart.CanCollide = false\n    motePart.CanTouch = false\n    motePart.CanQuery = false\n    motePart.Anchored = true\n    motePart.Parent = workspace.Terrain\nend\n\nlocal moteEmitter = motePart:FindFirstChild(\"Motes\") :: ParticleEmitter?\nif not moteEmitter then\n    moteEmitter = Instance.new(\"ParticleEmitter\")\n    moteEmitter.Name = \"Motes\"\n    moteEmitter.Texture = \"rbxasset://textures/particles/sparkles_main.dds\"\n    moteEmitter.Size = NumberSequence.new({\n        NumberSequenceKeypoint.new(0, 0.08),\n        NumberSequenceKeypoint.new(0.5, 0.16),\n        NumberSequenceKeypoint.new(1, 0.05)\n    })\n    moteEmitter.Transparency = NumberSequence.new({\n        NumberSequenceKeypoint.new(0, 0.9),\n        NumberSequenceKeypoint.new(0.5, 0.45),\n        NumberSequenceKeypoint.new(1, 1)\n    })\n    moteEmitter.Color = ColorSequence.new(Color3.fromRGB(180, 240, 255))\n    moteEmitter.LightEmission = 0.5\n    moteEmitter.Rate = 0 -- Controlled dynamically\n    moteEmitter.Lifetime = NumberRange.new(1.8, 3.0)\n    moteEmitter.Speed = NumberRange.new(0.4, 1.2)\n    moteEmitter.SpreadAngle = Vector2.new(180, 180)\n    moteEmitter.Acceleration = Vector3.new(0, 0.6, 0)\n    moteEmitter.Drag = 0.8\n    moteEmitter.Parent = motePart\nend\n\n-- -----------------------------------------------------------------------------\n-- 4. SUBMERSION DETECTION WITH ACCURATE WATERLINE HYSTERESIS\n-- -----------------------------------------------------------------------------\nlocal isSubmerged = false\nlocal submersionProgress = 0 -- 0 (above water) to 1 (fully submerged)\nlocal cachedWaterSurfaceY = 0.0\nlocal waterCheckTimer = 0\n\nlocal function queryWaterSurfaceAt(pos: Vector3): number\n    local minCorner = Vector3.new(\n        math.floor(pos.X / 4) * 4,\n        -40,\n        math.floor(pos.Z / 4) * 4\n    )\n    local maxCorner = minCorner + Vector3.new(4, 64, 4)\n    local region = Region3.new(minCorner, maxCorner):ExpandToGrid(4)\n\n    local success, mats, occs = pcall(function()\n        return workspace.Terrain:ReadVoxels(region, 4)\n    end)\n\n    if success and mats then\n        for y = mats.Size.Y, 1, -1 do\n            if mats[1][y][1] == Enum.Material.Water and occs[1][y][1] > 0.05 then\n                return minCorner.Y + (y * 4)\n            end\n        end\n    end\n    return 0.0\nend\n\nlocal function checkCameraUnderwater(): boolean\n    local currentCam = workspace.CurrentCamera\n    if not currentCam then return false end\n\n    local camPos = currentCam.CFrame.Position\n\n    -- Periodically refresh local water surface elevation\n    waterCheckTimer = waterCheckTimer + 0.016\n    if waterCheckTimer > 0.30 then\n",
"        waterCheckTimer = 0\n        cachedWaterSurfaceY = queryWaterSurfaceAt(camPos)\n    end\n\n    -- Camera is only underwater if clearly beneath the water surface level\n    -- When submerged, camera stays submerged until it breaches surface (+0.05)\n    -- When above water, camera stays above until it plunges below surface (-0.15)\n    local thresholdY = cachedWaterSurfaceY + (isSubmerged and 0.05 or -0.15)\n    if camPos.Y > thresholdY then\n        return false\n    end\n\n    local minCorner = Vector3.new(\n        math.floor(camPos.X / 4) * 4,\n        math.floor(camPos.Y / 4) * 4,\n        math.floor(camPos.Z / 4) * 4\n    )\n    local maxCorner = minCorner + Vector3.new(4, 4, 4)\n    local region = Region3.new(minCorner, maxCorner):ExpandToGrid(4)\n\n    local success, materials, occupancies = pcall(function()\n        return workspace.Terrain:ReadVoxels(region, 4)\n    end)\n\n    if success and materials and materials[1] and materials[1][1] and materials[1][1][1] == Enum.Material.Water then\n        local minOccupancy = isSubmerged and 0.08 or 0.35\n        if occupancies and occupancies[1] and occupancies[1][1] and occupancies[1][1][1] > minOccupancy then\n            return true\n        end\n    end\n\n    return false\nend\n\n-- -----------------------------------------------------------------------------\n-- 5. RENDER STEPPED ENGINE (Audiovisual Post-Processing)\n-- -----------------------------------------------------------------------------\nlocal TARGET_TINT = Color3.fromRGB(150, 220, 240)\nlocal DEFAULT_TINT = Color3.fromRGB(255, 255, 255)\n\nlocal TARGET_FOG_COLOR = Color3.fromRGB(25, 95, 125)\nlocal DEFAULT_FOG_COLOR = Color3.fromRGB(192, 192, 192)\n\nRunService.RenderStepped:Connect(function(dt: number)\n    local currentlyUnderwater = checkCameraUnderwater()\n\n    -- State transition with zero annoying audio spam\n    if currentlyUnderwater ~= isSubmerged then\n        isSubmerged = currentlyUnderwater\n    end\n\n    -- Smooth progress interpolation (clean 0.15s ease)\n    local targetProgress = isSubmerged and 1.0 or 0.0\n    local speed = isSubmerged and 9 or 7\n    submersionProgress = submersionProgress + (targetProgress - submersionProgress) * math.clamp(dt * speed, 0, 1)\n\n    -- 1. ColorCorrection\n    underwaterCC.TintColor = DEFAULT_TINT:Lerp(TARGET_TINT, submersionProgress)\n    underwaterCC.Saturation = 0.18 * submersionProgress\n    underwaterCC.Contrast = 0.12 * submersionProgress\n    underwaterCC.Brightness = -0.03 * submersionProgress\n\n    -- 2. Optical Water Diffraction Blur\n    underwaterBlur.Size = 2.5 * submersionProgress\n\n    -- 3. Depth Fog Attenuation\n    if submersionProgress > 0.02 then\n        Lighting.FogStart = 0\n        Lighting.FogEnd = 100000 - (100000 - 85) * submersionProgress\n        Lighting.FogColor = DEFAULT_FOG_COLOR:Lerp(TARGET_FOG_COLOR, submersionProgress)\n    else\n        Lighting.FogEnd = 100000\n    end\n\n    -- 4. Audio Low-Pass Equalizer\n    underwaterEQ.HighGain = -32 * submersionProgress\n",
"    underwaterEQ.MidGain = -8 * submersionProgress\n    underwaterEQ.LowGain = 4 * submersionProgress\n\n    -- 5. Motes Particle Emitter follow camera\n    if submersionProgress > 0.4 then\n        local currentCam = workspace.CurrentCamera\n        if currentCam then\n            motePart.CFrame = currentCam.CFrame * CFrame.new(0, 0, -4)\n            moteEmitter.Rate = 12 * submersionProgress\n        end\n    else\n        moteEmitter.Rate = 0\n    end\nend)\n\n",
}
local underwater_src = table.concat(underwater_chunks)

local sitting_chunks = {
"--!strict\n--[[\n    SittingController.client.lua\n    Universal Dynamic Sitting & Seating Transition System for \"Don't Let the Fire Die\".\n    Developed for Fluenosity Studio.\n\n    Features:\n    - Eliminates ugly Roblox default sit animation across all seats (campfires, logs, chairs, benches, vehicles).\n    - Authentic 3-Phase Animation Pipeline:\n        1. Stand to Sit: rbxassetid://84740804971115 (~2.23s natural lowering into seat)\n        2. Sitting Idle: rbxassetid://111666571897686 (4.00s loop, relaxed seated breathing posture)\n        3. Sit to Stand: rbxassetid://94330775048617 (~2.27s rising out of seat)\n    - Instant Movement-Cancel: if the player moves (W/A/S/D or mobile thumbstick) while standing up,\n      SitToStand instantly cancels with a 0.1s crossfade into walk/run with zero latency.\n    - Full First-Person and Third-Person camera compatibility.\n]]\n\nlocal Players = game:GetService(\"Players\")\nlocal UserInputService = game:GetService(\"UserInputService\")\nlocal RunService = game:GetService(\"RunService\")\n\nlocal localPlayer = Players.LocalPlayer\n\n-- -----------------------------------------------------------------------------\n-- 1. ANIMATION ASSET CONSTANTS\n-- -----------------------------------------------------------------------------\nlocal STAND_TO_SIT_ID = \"rbxassetid://84740804971115\"\nlocal SITTING_IDLE_ID = \"rbxassetid://111666571897686\"\nlocal SIT_TO_STAND_ID = \"rbxassetid://94330775048617\"\n\n-- -----------------------------------------------------------------------------\n-- 2. STATE & TRACK INSTANCES\n-- -----------------------------------------------------------------------------\nlocal activeCharacter: Model? = nil\nlocal activeHumanoid: Humanoid? = nil\nlocal activeRootPart: BasePart? = nil\nlocal activeAnimator: Animator? = nil\n\nlocal standToSitTrack: AnimationTrack? = nil\nlocal sittingIdleTrack: AnimationTrack? = nil\nlocal sitToStandTrack: AnimationTrack? = nil\n\nlocal isCurrentlySeated = false\nlocal transitionToken = 0\n\n-- -----------------------------------------------------------------------------\n-- 3. TRACK FACTORY & SUPPRESSION\n-- -----------------------------------------------------------------------------\nlocal function getOrCreateTrack(animator: Animator, animId: string, trackName: string, looped: boolean): AnimationTrack?\n    local anim = Instance.new(\"Animation\")\n    anim.Name = trackName\n    anim.AnimationId = animId\n    local success, track = pcall(function()\n        return animator:LoadAnimation(anim)\n    end)\n    if success and track then\n        track.Priority = Enum.AnimationPriority.Action4\n        track.Looped = looped\n        return track\n    end\n    return nil\nend\n\nlocal function stopTrack(track: AnimationTrack?, fadeTime: number)\n    if track then\n        pcall(function()\n            track:Stop(fadeTime)\n        end)\n    end\nend\n\nlocal function suppressDefaultRobloxSit()\n    if not activeAnimator then return end\n    for _, track in ipairs(activeAnimator:GetPlayingAnimationTracks()) do\n",
"        if track ~= standToSitTrack and track ~= sittingIdleTrack and track ~= sitToStandTrack then\n            local animName = track.Name:lower()\n            if animName == \"sit\" or string.find(animName, \"sit\") then\n                pcall(function()\n                    track:Stop(0.05)\n                end)\n            end\n        end\n    end\nend\n\n-- -----------------------------------------------------------------------------\n-- 4. SEATED TRANSITION LOGIC\n-- -----------------------------------------------------------------------------\nlocal function onEnterSeat(seat: Seat | VehicleSeat)\n    if isCurrentlySeated then return end\n    isCurrentlySeated = true\n    transitionToken = transitionToken + 1\n    local currentToken = transitionToken\n\n    -- Stop any lingering standing up animation\n    stopTrack(sitToStandTrack, 0.1)\n\n    if not activeAnimator then return end\n\n    -- Load tracks if needed\n    if not standToSitTrack then\n        standToSitTrack = getOrCreateTrack(activeAnimator, STAND_TO_SIT_ID, \"CustomStandToSit\", false)\n    end\n    if not sittingIdleTrack then\n        sittingIdleTrack = getOrCreateTrack(activeAnimator, SITTING_IDLE_ID, \"CustomSittingIdle\", true)\n    end\n\n    -- Immediately suppress Roblox default sit animation\n    suppressDefaultRobloxSit()\n\n    -- Phase 1: Play StandToSit transition\n    if standToSitTrack then\n        standToSitTrack:Play(0.15)\n        standToSitTrack:AdjustSpeed(1.15) -- Crisp, responsive sit timing (~1.9s)\n    end\n\n    -- Phase 2: Smooth crossfade into SittingIdle loop\n    task.delay(1.75, function()\n        if currentToken == transitionToken and isCurrentlySeated then\n            if sittingIdleTrack and not sittingIdleTrack.IsPlaying then\n                sittingIdleTrack:Play(0.3)\n                sittingIdleTrack:AdjustSpeed(1.0)\n            end\n            stopTrack(standToSitTrack, 0.25)\n        end\n    end)\nend\n\nlocal function hasActiveMoveIntent(): boolean\n    if not activeHumanoid then return false end\n    if activeHumanoid.MoveDirection.Magnitude > 0.08 then\n        return true\n    end\n    return UserInputService:IsKeyDown(Enum.KeyCode.W)\n        or UserInputService:IsKeyDown(Enum.KeyCode.A)\n        or UserInputService:IsKeyDown(Enum.KeyCode.S)\n        or UserInputService:IsKeyDown(Enum.KeyCode.D)\n        or UserInputService:IsKeyDown(Enum.KeyCode.Up)\n        or UserInputService:IsKeyDown(Enum.KeyCode.Down)\n        or UserInputService:IsKeyDown(Enum.KeyCode.Left)\n        or UserInputService:IsKeyDown(Enum.KeyCode.Right)\nend\n\nlocal function onLeaveSeat()\n    if not isCurrentlySeated then return end\n    isCurrentlySeated = false\n    transitionToken = transitionToken + 1\n    local currentToken = transitionToken\n\n    -- Stop sitting animations\n    stopTrack(standToSitTrack, 0.1)\n    stopTrack(sittingIdleTrack, 0.15)\n\n    -- If player is actively moving (WASD / Thumbstick), skip SitToStand for zero-latency instant run\n    if hasActiveMoveIntent() then\n        return\n    end\n\n",
"    if not activeAnimator then return end\n\n    if not sitToStandTrack then\n        sitToStandTrack = getOrCreateTrack(activeAnimator, SIT_TO_STAND_ID, \"CustomSitToStand\", false)\n    end\n\n    if sitToStandTrack then\n        sitToStandTrack:Play(0.15)\n        sitToStandTrack:AdjustSpeed(1.20) -- Natural brisk stand-up pace (~1.85s)\n\n        -- If at any point the player begins moving during the animation, instantly cancel it\n        local moveConn: RBXScriptSignal? = nil\n        local keyConn: RBXScriptSignal? = nil\n\n        local function cancelForMovement()\n            if sitToStandTrack and sitToStandTrack.IsPlaying then\n                sitToStandTrack:Stop(0.1)\n            end\n            if moveConn then moveConn:Disconnect() moveConn = nil end\n            if keyConn then keyConn:Disconnect() keyConn = nil end\n        end\n\n        if activeHumanoid then\n            moveConn = activeHumanoid:GetPropertyChangedSignal(\"MoveDirection\"):Connect(function()\n                if hasActiveMoveIntent() then\n                    cancelForMovement()\n                end\n            end)\n        end\n\n        keyConn = UserInputService.InputBegan:Connect(function(input, gpe)\n            if gpe then return end\n            if input.KeyCode == Enum.KeyCode.W or input.KeyCode == Enum.KeyCode.A or input.KeyCode == Enum.KeyCode.S or input.KeyCode == Enum.KeyCode.D then\n                cancelForMovement()\n            end\n        end)\n\n        sitToStandTrack.Stopped:Connect(function()\n            if moveConn then moveConn:Disconnect() moveConn = nil end\n            if keyConn then keyConn:Disconnect() keyConn = nil end\n        end)\n    end\nend\n\n-- -----------------------------------------------------------------------------\n-- 5. CHARACTER RIGGING & SEATED MONITOR\n-- -----------------------------------------------------------------------------\nlocal function cleanupTracks()\n    stopTrack(standToSitTrack, 0.1)\n    stopTrack(sittingIdleTrack, 0.1)\n    stopTrack(sitToStandTrack, 0.1)\n    standToSitTrack = nil\n    sittingIdleTrack = nil\n    sitToStandTrack = nil\n    isCurrentlySeated = false\nend\n\nlocal function setupCharacter(char: Model)\n    cleanupTracks()\n    activeCharacter = char\n    activeHumanoid = char:WaitForChild(\"Humanoid\", 10) :: Humanoid?\n    activeRootPart = char:WaitForChild(\"HumanoidRootPart\", 10) :: BasePart?\n    activeAnimator = if activeHumanoid then (activeHumanoid:WaitForChild(\"Animator\", 10) :: Animator?) else nil\n\n    if not activeHumanoid then return end\n\n    -- Monitor Seated state\n    activeHumanoid.Seated:Connect(function(active: boolean, currentSeat: Instance?)\n        if active and currentSeat and (currentSeat:IsA(\"Seat\") or currentSeat:IsA(\"VehicleSeat\")) then\n            onEnterSeat(currentSeat :: any)\n        else\n            onLeaveSeat()\n        end\n    end)\n\n    -- Extra safety check for Humanoid.Sit property\n    activeHumanoid:GetPropertyChangedSignal(\"Sit\"):Connect(function()\n        if not activeHumanoid then return end\n",
"        if not activeHumanoid.Sit and isCurrentlySeated then\n            onLeaveSeat()\n        end\n    end)\nend\n\nif localPlayer.Character then\n    setupCharacter(localPlayer.Character)\nend\n\nlocalPlayer.CharacterAdded:Connect(setupCharacter)\nlocalPlayer.CharacterRemoving:Connect(function()\n    cleanupTracks()\n    activeCharacter = nil\n    activeHumanoid = nil\n    activeRootPart = nil\n    activeAnimator = nil\nend)\n\n-- Background loop to suppress default Roblox sit track if it ever attempts to play\nRunService.Heartbeat:Connect(function()\n    if isCurrentlySeated then\n        suppressDefaultRobloxSit()\n    end\nend)\n\n",
}
local sitting_src = table.concat(sitting_chunks)


local results = {}
local player = game:GetService("Players").LocalPlayer
local pScripts = player and player:FindFirstChild("PlayerScripts")
local fluenClient = pScripts and pScripts:FindFirstChild("FluenosityClient")

if fluenClient then
    local sc = fluenClient:FindFirstChild("SwimmingController")
    if sc then
        sc.Source = swim_src
        table.insert(results, "Updated Client SwimmingController")
    end

    local uc = fluenClient:FindFirstChild("UnderwaterController")
    if uc then
        uc.Source = underwater_src
        table.insert(results, "Updated Client UnderwaterController")
    end

    local st = fluenClient:FindFirstChild("SittingController")
    if not st then
        st = Instance.new("LocalScript")
        st.Name = "SittingController"
        st.Parent = fluenClient
    end
    st.Source = sitting_src
    table.insert(results, "Updated Client SittingController")
end

local sps = game:GetService("StarterPlayer"):FindFirstChild("StarterPlayerScripts")
local spsFluen = sps and sps:FindFirstChild("FluenosityClient")
if spsFluen then
    local sc = spsFluen:FindFirstChild("SwimmingController")
    if sc then
        sc.Source = swim_src
        table.insert(results, "Updated StarterPlayer SwimmingController")
    end

    local uc = spsFluen:FindFirstChild("UnderwaterController")
    if uc then
        uc.Source = underwater_src
        table.insert(results, "Updated StarterPlayer UnderwaterController")
    end

    local st = spsFluen:FindFirstChild("SittingController")
    if not st then
        st = Instance.new("LocalScript")
        st.Name = "SittingController"
        st.Parent = spsFluen
    end
    st.Source = sitting_src
    table.insert(results, "Updated StarterPlayer SittingController")
end

return table.concat(results, "\n")
